/**
 * Test flow for waitForMessage action
 * Demonstrates waiting for a message from the flow API
 */

import { action, Flow, wfa, trigger } from '@servicenow/sdk/automation'

export const testWaitForMessage = Flow(
    {
        $id: Now.ID['test_wait_for_message_flow'],
        name: 'Test Wait For Message',
        description: 'Tests the waitForMessage core action',
    },
    wfa.trigger(
        trigger.record.created,
        { $id: Now.ID['test_wait_for_message_trigger'] },
        {
            table: 'incident',
            condition: 'active=true',
            run_flow_in: 'background',
        }
    ),
    (_params) => {
        const result = wfa.action(
            action.core.waitForMessage,
            { $id: Now.ID['test_wait_for_message_action'] },
            {
                message: 'approval_received',
                timeout: '10:00:00',
                enable_timeout: true,
            }
        )

        wfa.action(
            action.core.log,
            { $id: Now.ID['test_wait_for_message_log'] },
            {
                log_level: 'info',
                log_message: `waitForMessage outputs: payload=${wfa.dataPill(result.payload, 'string')}`,
            }
        )
    }
)
